# Corefile
.:53 {
    forward . 8.8.8.8 8.8.4.4
    cache 30
    log
    errors
}

example.com:53 {
    file /etc/coredns/example.com.zone
    log
}

# CoreDNS生产环境高性能配置
apiVersion: v1
kind: ConfigMap
metadata:
  name: coredns-performance-config
  namespace: kube-system
data:
  Corefile: |
    .:53 {
        # 高性能转发配置
        forward . 8.8.8.8 8.8.4.4 {
            max_concurrent 1000
            health_check 5s
            expire 30s
            policy sequential
        }

        # 高效缓存配置
        cache 300 {
            success 5000
            denial 2500
            prefetch 10 1m 10%
        }

        # 负载均衡
        loadbalance round_robin

        # 高性能选项
        bufsize 1232
        template IN A example.com {
            match .*\.example\.com
            answer "{{ .Name }} 60 IN A 10.0.0.1"
            fallthrough
        }

        # 监控和日志
        prometheus :9153
        log . {
            class error
        }
        errors
    }

    # 本地域名优化
    cluster.local:53 {
        kubernetes cluster.local in-addr.arpa ip6.arpa {
            pods insecure
            fallthrough in-addr.arpa ip6.arpa
            ttl 30
        }
        prometheus :9153
        forward . /etc/resolv.conf {
            max_concurrent 100
            health_check 10s
        }
        cache 30 {
            success 1000
            denial 100
        }
        reload
    }
